import { useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Polyline, Popup, CircleMarker, Tooltip, useMap } from 'react-leaflet';
import L from 'leaflet';
import markerIcon2x from 'leaflet/dist/images/marker-icon-2x.png';
import markerIcon from 'leaflet/dist/images/marker-icon.png';
import markerShadow from 'leaflet/dist/images/marker-shadow.png';

// Create React App breaks Leaflet's default marker image paths; fix them once.
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({ iconRetinaUrl: markerIcon2x, iconUrl: markerIcon, shadowUrl: markerShadow });

const boatIcon = new L.Icon({
  iconUrl: '/boat-icon.png',
  iconSize: [36, 36],
  iconAnchor: [18, 18],
  popupAnchor: [0, -18],
});

const KOCHI_CENTER = [10.01, 76.29];

/** Zooms the map to fit the given points whenever they change. */
const FitBounds = ({ points }) => {
  const map = useMap();
  useEffect(() => {
    if (points.length >= 2) map.fitBounds(points, { padding: [40, 40] });
  }, [map, points]);
  return null;
};

/**
 * stations:     { "High Court": [lat, lng], ... }
 * routePoints:  [[lat, lng], ...] for the selected trip (empty if none)
 * routeStops:   station names along that trip
 * boat:         { position: [lat, lng], label, info } or null
 */
const TrackingMap = ({ stations, routePoints, routeStops, boat }) => (
  <MapContainer center={KOCHI_CENTER} zoom={12} className="tracking-map">
    <TileLayer
      url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      attribution="&copy; OpenStreetMap contributors"
    />

    {/* every terminal as a small dot */}
    {Object.entries(stations).map(([name, pos]) => (
      <CircleMarker
        key={name}
        center={pos}
        radius={6}
        pathOptions={{ color: '#0b5ed7', fillColor: '#fff', fillOpacity: 1, weight: 3 }}
      >
        <Tooltip>{name}</Tooltip>
      </CircleMarker>
    ))}

    {routePoints.length >= 2 && (
      <>
        <Polyline positions={routePoints} pathOptions={{ color: '#00b4d8', weight: 5, dashArray: '8 8' }} />
        <Marker position={routePoints[0]}><Popup>Start: {routeStops[0]}</Popup></Marker>
        <Marker position={routePoints[routePoints.length - 1]}>
          <Popup>Destination: {routeStops[routeStops.length - 1]}</Popup>
        </Marker>
        <FitBounds points={routePoints} />
      </>
    )}

    {boat && (
      <Marker position={boat.position} icon={boatIcon} zIndexOffset={1000}>
        <Popup><strong>{boat.label}</strong><br />{boat.info}</Popup>
      </Marker>
    )}
  </MapContainer>
);

export default TrackingMap;
